<?php
declare(strict_types=1);
require __DIR__.'/hybrid-isolation.php';
$m=HybridIsolationHarness::manifest($argv[1]??'');$p=HybridIsolationHarness::connection($m);App\Services\HybridDatabaseScope::verify($p,$m);$f=json_decode(file_get_contents($m['directory'].'/fixtures-stage5.json'),true);$service=new App\Services\Reports($p);$actor=(new App\Services\Invoices($p))->actor($f['admin']);$checks=0;
$check=static function(bool$ok,string$label)use(&$checks){if(!$ok)throw new RuntimeException($label);$checks++;};
$render=static function(string$locale,bool$csv)use($service,$f,$actor):string{App\Support\I18n::set($locale);$_COOKIE['dharma_language']=$locale;$_SESSION=['csrf_token'=>str_repeat('a',64)];$_GET=['period'=>'today','customer_id'=>$f['fixtures']['customers']['rep1']];$_POST=[];$_SERVER['REQUEST_METHOD']='GET';$_SERVER['REQUEST_URI']='/admin/reports/hybridreturns'.($csv?'/csv':'');$route=App\Controllers\ReportController::route($_SERVER['REQUEST_URI']);ob_start();(new App\Controllers\ReportController($service))->handle($route,$actor);return ob_get_clean();};
$en=$render('en',false);$si=$render('si-LK',false);$check(str_contains($en,'original_gross_reversed_lkr'),'English field labels preserved');$check(str_contains($si,'ආපසු හරවන මුල් දළ වටිනාකම'),'Sinhala Hybrid header');$check(str_contains($si,'data-source-field="original_gross_reversed_lkr"'),'Machine field unchanged');$check(str_contains($si,'වගකීමකි; මුදල් ගෙවීමක් නොවේ'),'Liability note translated');
$parse=static function($csv):array{$h=fopen('php://temp','r+');fwrite($h,$csv);rewind($h);$rows=[];while(($row=fgetcsv($h))!==false)$rows[]=$row;fclose($h);return$rows;};$a=$parse($render('en',true));$b=$parse($render('si-LK',true));$check(count($a)>1,'Synthetic report contains returns');$check($a[0]!==$b[0],'Presentation headers localized');$check(array_slice($a,1)===array_slice($b,1),'CSV financial rows and identities identical');$check(str_contains($b[0][0],'මුල් බිල්පත'),'Sinhala CSV header');
file_put_contents($m['directory'].'/stage6c-report-locale.json',json_encode(['checks'=>$checks,'csv_data_identical'=>true,'native_approval'=>false],JSON_PRETTY_PRINT));echo "Stage 6C report localization: $checks checks passed; CSV data and financial keys unchanged.\n";
